/**
 * Zod schemas for the carousel REST API.
 *
 * Backend reference: backend/backend/docs/plans/SOI-624-carousel-apis.md §2.
 * Endpoints:
 *   GET  /api/v1/carousels?url=&slot=&website_code=                            → CarouselResponseSchema
 *   POST /api/v1/carousels/events                                              → CarouselEventBatchSchema (request)
 *
 * "Slot configured but empty" is served as a **200** carrying the full
 * CarouselResponsePayload plus `status: "not_available"` and a `reason`
 * (verified live against service-staging) — so it is parsed by
 * CarouselResponseSchema, exactly like any other 200. CarouselNotAvailableSchema
 * covers only the bare `{ status, reason }` 204 body, which fetchCarousel
 * short-circuits to CAROUSEL_EMPTY without parsing.
 *
 * Shape-first per Non-Negotiable #2.
 */

import { z } from 'zod';

const NumOrString = z.union([z.number(), z.string()]);

// ── Money ──────────────────────────────────────────────────────
// Two real-world shapes observed against service-staging.omniguide.ai:
//   1. Plain scalar (Rogers seed):   "price": "239.99"
//   2. Structured object (planned):  "price": { "amount": "49.99", "currency": "USD" }
// Schema accepts both so SDK consumers don't need to re-fetch when the
// backend evolves; CarouselCard.formatPrice does the runtime branching.

export const CarouselPriceObjectSchema = z.object({
  amount: z.union([z.string(), z.number()]),
  // Nullable, not just optional: the backend hard-codes "USD" today, but
  // `_price_payload` is commented to swap in `website_currency()`, which
  // returns None for a tenant with no currency configured — that would
  // serialize as `"currency": null` and, under a bare `.optional()`, reject
  // the whole carousel. `CarouselCardProps.defaultCurrency` exists precisely
  // to cover a missing currency, so the schema must let null reach it.
  currency: z.string().nullable().optional(),
  // When true, the amount is the min over variants (different sizes /
  // colors / configurations) rather than a single fixed price — UI
  // renders a "Starting at" prefix. Backend doesn't emit this for any
  // tenant yet; SDK accepts it so the contract is forward-compatible.
  from: z.boolean().optional(),
}).passthrough();

export const CarouselPriceSchema = z.union([
  z.string(),
  z.number(),
  CarouselPriceObjectSchema,
]);

// ── Slot product ───────────────────────────────────────────────

export const CarouselSlotProductSchema = z.object({
  sku: z.string(),
  title: z.string().nullable().optional(),
  image_url: z.string().nullable().optional(),
  url: z.string().nullable().optional(),
  price: CarouselPriceSchema.nullable().optional(),
  // Display-only brand label (e.g., "TRACT OPTICS"). Optional — backend
  // populates when product feed carries it; tile gracefully omits otherwise.
  brand: z.string().nullable().optional(),
  // Compare-at / strike-through price for sale items. Same shape as `price`.
  compare_at_price: CarouselPriceSchema.nullable().optional(),
}).passthrough();

// ── Narrative (precomputed; can be null when cron hasn't filled yet) ──

export const CarouselNarrativeSchema = z.object({
  variant_id: z.string().default('default'),
  headline: z.string().nullable().optional(),
  body: z.string().nullable().optional(),
  hash: z.string().nullable().optional(),
}).passthrough();

// ── Per-slot scoring (logged, not rendered) ─────────────────────

export const CarouselSlotScoringSchema = z.object({
  served_propensity: z.number().optional(),
  exploration: z.boolean().optional(),
  raw_score: z.number().nullable().optional(),
}).passthrough();

// ── Pin metadata (when source ∈ pinned_rule | pinned_forced) ────

export const CarouselSlotPinSchema = z.object({
  rule_id: z.number().nullable().optional(),
  reason: z.string().nullable().optional(),
}).passthrough();

// ── Single slot ────────────────────────────────────────────────

export const CarouselSlotSchema = z.object({
  position: z.number(),
  product: CarouselSlotProductSchema,
  narrative: CarouselNarrativeSchema.nullable(),
  scoring: CarouselSlotScoringSchema.optional(),
  // source ∈ fbt | ymal | trending | pinned_rule | pinned_forced — kept loose
  source: z.string().optional(),
  pin: CarouselSlotPinSchema.nullable().optional(),
}).passthrough();

// ── Anchor (PDP = sku, CMS pages = tenant) ─────────────────────

export const CarouselAnchorSchema = z.object({
  type: z.string(), // 'sku' | 'tenant' | 'category' | 'page_type'
  value: z.string().nullable().optional(),
}).passthrough();

// ── Cache metadata ─────────────────────────────────────────────

export const CarouselCacheSchema = z.object({
  key: z.string().nullable().optional(),
  ttl_seconds: z.number().optional(),
  expires_at: z.string().nullable().optional(),
}).passthrough();

// ── Top-level response ─────────────────────────────────────────

export const CarouselResponseSchema = z.object({
  carousel_id: z.string(),
  website_code: z.string(),
  slot_code: z.string(),
  strategy: z.string(),
  anchor: CarouselAnchorSchema,
  policy_snapshot_id: z.string().optional(),
  model_version: z.string().optional(),
  slots: z.array(CarouselSlotSchema).default([]),
  cache: CarouselCacheSchema.optional(),
}).passthrough();

// ── 204 not-available body ─────────────────────────────────────

export const CarouselNotAvailableSchema = z.object({
  status: z.literal('not_available'),
  // Backend model is `reason: Optional[str] = None` (CarouselResponsePayload),
  // and it does not serialize with `exclude_none` — a not-available body with
  // no machine reason ships `"reason": null`, which a bare `.optional()`
  // rejects. Observed as an explicit null on real 200 bodies.
  reason: z.string().nullable().optional(),
}).passthrough();

// ── Event ingest (request shape only) ──────────────────────────

export const CarouselEventItemSchema = z.object({
  item_id: z.string(),
  index: z.number().optional(),
  quantity: z.number().optional(),
  price: NumOrString.optional(),
}).passthrough();

export const CarouselEventSchema = z.object({
  event_name: z.enum(['view_item_list', 'select_item', 'select_promotion', 'add_to_cart', 'purchase']),
  carousel_id: z.string(),
  item_list_id: z.string().optional(),
  items: z.array(CarouselEventItemSchema).default([]),
  timestamp: z.string(),
  session_id: z.string(),
  page_url: z.string(),
}).passthrough();

export const CarouselEventBatchSchema = z.object({
  website_code: z.string(),
  events: z.array(CarouselEventSchema).default([]),
}).passthrough();

// ── Inferred types ─────────────────────────────────────────────

export type CarouselResponse = z.infer<typeof CarouselResponseSchema>;
export type CarouselSlot = z.infer<typeof CarouselSlotSchema>;
export type CarouselSlotProduct = z.infer<typeof CarouselSlotProductSchema>;
export type CarouselNarrative = z.infer<typeof CarouselNarrativeSchema>;
export type CarouselSlotScoring = z.infer<typeof CarouselSlotScoringSchema>;
export type CarouselSlotPin = z.infer<typeof CarouselSlotPinSchema>;
export type CarouselAnchor = z.infer<typeof CarouselAnchorSchema>;
export type CarouselPrice = z.infer<typeof CarouselPriceSchema>;
export type CarouselNotAvailable = z.infer<typeof CarouselNotAvailableSchema>;
export type CarouselEvent = z.infer<typeof CarouselEventSchema>;
export type CarouselEventBatch = z.infer<typeof CarouselEventBatchSchema>;
export type CarouselEventItem = z.infer<typeof CarouselEventItemSchema>;
